@extends('layout') @section('content')<h1>{{ $title }} · {{ $row->exists?'Editar':'Crear' }}</h1><form method="post" action="{{ $row->exists?route('admin.update',[$resource,$row->id]):route('admin.store',$resource) }}">@csrf @if($row->exists) @method('put') @endif<input type="hidden" name="record_token" value="{{ hash('sha256',json_encode($row->getAttributes())) }}"><input type="hidden" name="updated_at" value="{{ $row->updated_at }}"><input type="hidden" name="version" value="{{ $row->version }}">@foreach($fields as $f=>$label)<label>{{ $label }}@if(isset($options[$f]))<select name="{{ $f }}{{ $f==='roles'?'[]':'' }}" @if($f==='roles') multiple @endif>@if($f!=='roles')<option value="">Seleccione</option>@endif @foreach($options[$f] as $o)<option value="{{ $o->id }}" @selected($f==='roles'?in_array($o->id,old('roles',$row->exists?$row->roles->pluck('id')->all():[])):(string)old($f,$row->$f)===(string)$o->id)>{{ $o->name }}</option>@endforeach</select>@elseif(in_array($f,['active','is_deposit']))<select name="{{ $f }}"><option value="1" @selected(old($f,$row->$f??($f==='active'))==1)>Sí</option><option value="0" @selected(old($f,$row->$f??($f==='active'))==0)>No</option></select>@else<input name="{{ $f }}" type="{{ match($f){'password'=>'password','email'=>'email','registered_on'=>'date','value'=>'number',default=>'text'} }}" @if($f==='value') step="0.01" min="0" @endif value="{{ $f==='password'?'':old($f,$f==='registered_on'?$row->$f?->format('Y-m-d'):$row->$f) }}">@endif</label>@endforeach<label>Motivo del registro o cambio<textarea name="reason" required>{{ old('reason') }}</textarea></label><p>Revise los datos antes de guardar. El cambio quedará auditado.</p><button>Guardar registro</button></form>@endsection